import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), q = nextInt();
        HashMap<String, String> table = new HashMap<>(2 * n);
        for (int i = 0; i < n; i++) {
            String t = next(), k = next(), v = next();
            table.put(k + " " + t, v); // composite key (key, timestamp)
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String k = next(), t = next();
            out.append(table.get(k + " " + t)).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, q := int(nextInt()), int(nextInt())
	table := make(map[string][]byte, n)
	for i := 0; i < n; i++ {
		t, k, v := next(), next(), next()
		table[string(k)+" "+string(t)] = v // composite key (key, timestamp)
	}
	for i := 0; i < q; i++ {
		k, t := next(), next()
		w.Write(table[string(k)+" "+string(t)])
		w.WriteByte('\n')
	}
	_ = strconv.Itoa
}
